import React, { useState } from 'react';
import { Moon, Sun, Menu, X } from 'lucide-react';
import { nav } from '../data/content';

export default function Navbar({ activeSection, darkMode, onToggleDark, onNavClick }) {
  const [open, setOpen] = useState(false);

  const handleClick = (id) => {
    onNavClick(id);
    setOpen(false);
  };

  return (
    <header className="fixed top-0 inset-x-0 z-50 border-b border-zinc-200/70 dark:border-zinc-800/70 bg-zinc-50/80 dark:bg-zinc-950/80 backdrop-blur-md">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">
        <a
          href="#top"
          onClick={(e) => { e.preventDefault(); handleClick('top'); }}
          className="flex items-center gap-2 font-display font-semibold text-zinc-900 dark:text-zinc-50"
        >
          <span className="flex items-center justify-center w-8 h-8 rounded-lg bg-indigo-500 text-white text-sm font-mono">
            CM
          </span>
          <span className="hidden sm:inline">Chetanya Makkar</span>
        </a>

        {/* Desktop nav */}
        <nav className="hidden md:flex items-center gap-1 font-mono text-sm">
          {nav.map((item) => (
            <a
              key={item.id}
              href={`#${item.id}`}
              onClick={(e) => { e.preventDefault(); handleClick(item.id); }}
              className={`px-3 py-1.5 rounded-full transition-colors ${
                activeSection === item.id
                  ? 'bg-indigo-500/10 text-indigo-600 dark:text-indigo-400'
                  : 'text-zinc-600 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100'
              }`}
            >
              {item.label}
            </a>
          ))}
        </nav>

        <div className="flex items-center gap-2">
          <span className="hidden lg:flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-mono bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
            <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
            Open to chat
          </span>
          <button
            onClick={onToggleDark}
            aria-label="Toggle theme"
            className="p-2 rounded-full text-zinc-600 dark:text-zinc-300 hover:bg-zinc-200 dark:hover:bg-zinc-800 transition-colors"
          >
            {darkMode ? <Sun size={18} /> : <Moon size={18} />}
          </button>
          <button
            onClick={() => setOpen((o) => !o)}
            aria-label="Toggle menu"
            className="md:hidden p-2 rounded-full text-zinc-600 dark:text-zinc-300 hover:bg-zinc-200 dark:hover:bg-zinc-800 transition-colors"
          >
            {open ? <X size={18} /> : <Menu size={18} />}
          </button>
        </div>
      </div>

      {/* Mobile nav */}
      {open && (
        <nav className="md:hidden border-t border-zinc-200 dark:border-zinc-800 bg-zinc-50 dark:bg-zinc-950 px-4 py-3 flex flex-col gap-1 font-mono text-sm">
          {nav.map((item) => (
            <a
              key={item.id}
              href={`#${item.id}`}
              onClick={(e) => { e.preventDefault(); handleClick(item.id); }}
              className={`px-3 py-2 rounded-lg transition-colors ${
                activeSection === item.id
                  ? 'bg-indigo-500/10 text-indigo-600 dark:text-indigo-400'
                  : 'text-zinc-600 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100'
              }`}
            >
              {item.label}
            </a>
          ))}
        </nav>
      )}
    </header>
  );
}
